const uint16_t* backgroundImageData() {
    return kBackgroundImageData;
}

uint16_t backgroundImagePixel(std::size_t x, std::size_t y) {
    if (x >= BACKGROUND_IMAGE_WIDTH || y >= BACKGROUND_IMAGE_HEIGHT) {
        return BACKGROUND_IMAGE_FALLBACK_RGB565;
    }
    return kBackgroundImageData[(y * BACKGROUND_IMAGE_WIDTH) + x];
}
